// Like Feign but Spring-native. No extra dependency.
package com.bank.trading.client;

import com.bank.trading.dto.PriceUpdate;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.service.annotation.GetExchange;
import org.springframework.web.service.annotation.HttpExchange;

@HttpExchange("/api/v1/prices")
public interface ExchangeClient {

    @GetExchange("/{symbol}")
    PriceUpdate getPrice(@PathVariable String symbol);

    @GetExchange("/{symbol}/history")
    java.util.List<PriceUpdate> getPriceHistory(@PathVariable String symbol);
}
