// Flux<PriceUpdate>: reactive stream for WebSocket and SSE
package com.bank.trading.service;

import com.bank.trading.dto.PriceUpdate;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Flux;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Duration;
import java.time.LocalDateTime;

@Service
@Slf4j
public class PriceFeedService {

    // Simulates a live price stream — in real app, connected to exchange feed
    public Flux<PriceUpdate> getPriceStream(String symbol) {
        return Flux.interval(Duration.ofSeconds(1))
            .map(tick -> {
                BigDecimal price = new BigDecimal("2450")
                    .add(BigDecimal.valueOf(Math.random() * 20 - 10))
                    .setScale(2, RoundingMode.HALF_UP);
                BigDecimal change = price.subtract(new BigDecimal("2450"));
                return new PriceUpdate(symbol, price, change, LocalDateTime.now());
            })
            .doOnSubscribe(s -> log.info("Client subscribed to {} price feed", symbol))
            .doOnCancel(() -> log.info("Client disconnected from {} price feed", symbol));
    }
}
