package com.bank.trading.controller;

import com.bank.trading.dto.PriceUpdate;
import com.bank.trading.service.PriceFeedService;
import lombok.RequiredArgsConstructor;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.*;
import reactor.core.publisher.Flux;

@RestController
@RequestMapping("/api/v1/prices")
@RequiredArgsConstructor
public class PriceSseController {

    private final PriceFeedService priceFeedService;

    // SSE: text/event-stream — browser auto-reconnects
    @GetMapping(value = "/stream/{symbol}", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public Flux<PriceUpdate> streamPrices(@PathVariable String symbol) {
        return priceFeedService.getPriceStream(symbol);
    }
}
