package com.bank.trading.controller;

import com.bank.trading.dto.PriceUpdate;
import com.bank.trading.service.PriceFeedService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.messaging.handler.annotation.*;
import org.springframework.messaging.simp.SimpMessagingTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Controller;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDateTime;

@Controller
@RequiredArgsConstructor
@Slf4j
public class PriceWebSocketHandler {

    private final SimpMessagingTemplate messagingTemplate;

    // Client sends: /app/subscribe-price with symbol
    @MessageMapping("/subscribe-price")
    @SendTo("/topic/prices")
    public PriceUpdate subscribeToPrice(String symbol) {
        log.info("WebSocket: client subscribed to {}", symbol);
        return new PriceUpdate(symbol, new BigDecimal("2450.50"), BigDecimal.ZERO, LocalDateTime.now());
    }

    // Push prices every second to all subscribers
    @Scheduled(fixedRate = 1000)
    public void pushPriceUpdates() {
        BigDecimal price = new BigDecimal("2450")
            .add(BigDecimal.valueOf(Math.random() * 20 - 10))
            .setScale(2, RoundingMode.HALF_UP);
        messagingTemplate.convertAndSend("/topic/prices",
            new PriceUpdate("RELIANCE", price, price.subtract(new BigDecimal("2450")), LocalDateTime.now()));
    }
}
