package com.bank.trading.service;

import com.bank.trading.model.Trade;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import java.util.List;

@Service
@RequiredArgsConstructor
public class TradeService {

    private final EntityManager em;

    public Trade findById(String tradeId) {
        return em.find(Trade.class, tradeId);
    }

    public List<Trade> findByAccount(String accountId) {
        return em.createQuery("SELECT t FROM Trade t WHERE t.accountId = :id", Trade.class)
            .setParameter("id", accountId).getResultList();
    }
}
